/*
 * Vercel Function — /api/digistore-postback
 *
 * Receives the Digistore24 S2S postback, decodes the attribution `cid`
 * generated by tracking.js and forwards a validated conversion to Google Ads.
 *
 * Digistore24 placeholders used (official list, help.digistore24.com):
 *   {cid}              -> click_id
 *   {amount_affiliate} -> revenue
 *   {transaction_type} -> status        (payment | refund | chargeback | ...)
 *   {transaction_id}   -> transaction_id (unique per payment/refund/chargeback)
 *   {currency}         -> currency
 *   {is_test}          -> is_test
 *   {amount_brutto}    -> gross
 *
 * Google Ads: conversion fires through the googleadservices.com conversion
 * endpoint using Conversion ID + Conversion Label from environment variables.
 * `oid` (= Digistore24 transaction_id) makes Google drop duplicate reports.
 */

const CONVERSION_ENDPOINT = "https://www.googleadservices.com/pagead/conversion/";

/* In-memory dedupe (per warm instance). Google-side `oid` is the durable guard. */
const seen = new Map();
const SEEN_TTL_MS = 30 * 60 * 1000;

function pruneSeen() {
  const now = Date.now();
  for (const [k, t] of seen) {
    if (now - t > SEEN_TTL_MS) seen.delete(k);
  }
}

/* ---------- helpers ---------- */

function decodeCid(cid) {
  if (!cid || typeof cid !== "string") return null;
  try {
    let s = cid.replace(/-/g, "+").replace(/_/g, "/");
    while (s.length % 4) s += "=";
    const json = Buffer.from(s, "base64").toString("utf8");
    const obj = JSON.parse(json);
    return obj && typeof obj === "object" ? obj : null;
  } catch (e) {
    return null;
  }
}

function parseAmount(v) {
  if (v === undefined || v === null || v === "") return null;
  let s = String(v).trim().replace(/[^\d.,-]/g, "");
  // "1.234,56" -> 1234.56 ; "15,03" -> 15.03 ; "15.03" -> 15.03
  if (s.includes(",") && s.includes(".")) {
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) s = s.replace(/\./g, "").replace(",", ".");
    else s = s.replace(/,/g, "");
  } else if (s.includes(",")) {
    s = s.replace(",", ".");
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : null;
}

function normalizeStatus(status) {
  if (!status) return "";
  let s = String(status).trim().toLowerCase();
  if (s.startsWith("on_")) s = s.slice(3);
  return s;
}

function isTestFlag(isTest) {
  if (isTest === undefined || isTest === null || isTest === "") return false;
  const v = String(isTest).trim().toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

function numericConversionId(raw) {
  if (!raw) return null;
  const m = String(raw).trim().match(/^(?:AW-)?(\d+)$/);
  return m ? m[1] : null;
}

function buildGoogleUrl({ conversionId, label, value, currency, attr, orderId }) {
  const q = [];
  q.push(["label", label]);
  if (value !== null) q.push(["value", String(value)]);
  if (currency) q.push(["currency_code", currency]);
  if (attr && attr.g) q.push(["gclid", attr.g]);
  if (attr && attr.w) q.push(["wbraid", attr.w]);
  if (attr && attr.b) q.push(["gbraid", attr.b]);
  // order id -> Google drops the conversion if reported twice
  if (orderId) q.push(["oid", String(orderId)]);

  const qs = q
    .map(([k, v]) => encodeURIComponent(k) + "=" + encodeURIComponent(v))
    .join("&");
  return `${CONVERSION_ENDPOINT}${conversionId}/?${qs}`;
}

async function fireGoogleConversion(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(url, {
      method: "GET",
      signal: controller.signal,
      headers: { "User-Agent": "AminoFormula-Postback/1.0" }
    });
    return { ok: res.ok, status: res.status };
  } catch (e) {
    return { ok: false, status: 0, error: String(e && e.message ? e.message : e) };
  } finally {
    clearTimeout(timer);
  }
}

/* ---------- handler ---------- */

module.exports = async function handler(req, res) {
  // Digistore24 S2S postback is a GET with query params; accept POST too.
  const q = req.query || {};
  const body = req.body || {};
  const get = (k) => (q[k] !== undefined && q[k] !== "" ? q[k] : body[k]);

  const clickId = get("click_id") || get("cid");
  const revenueRaw = get("revenue");
  const rawStatus = get("status");
  const transactionId = get("transaction_id") || get("txid") || "";
  const currencyRaw = get("currency") || "";
  const isTest = isTestFlag(get("is_test"));
  const gross = parseAmount(get("gross") || get("amount_brutto"));
  const dryRun = String(get("dry_run") || "").toLowerCase() === "1";

  const status = normalizeStatus(rawStatus);
  const revenue = parseAmount(revenueRaw);

  const log = {
    received: {
      click_id: clickId || null,
      revenue: revenueRaw !== undefined ? revenueRaw : null,
      status: rawStatus !== undefined ? rawStatus : null,
      transaction_id: transactionId || null,
      currency: currencyRaw || null,
      is_test: isTest
    },
    decisions: {}
  };

  /* --- validation --- */
  if (!clickId) {
    log.error = "missing click_id (Digistore24 {cid})";
    return res.status(400).json(log);
  }
  if (!status) {
    log.error = "missing status (Digistore24 {transaction_type})";
    return res.status(400).json(log);
  }

  const attr = decodeCid(clickId);
  log.attribution = attr
    ? {
        vid: attr.v || null,
        gclid: attr.g || null,
        gbraid: attr.b || null,
        wbraid: attr.w || null,
        utm: attr.u || null
      }
    : null;
  if (!attr) {
    log.decisions.cid_decoded = false;
  }

  /* --- test transactions never become conversions --- */
  if (isTest) {
    log.decisions.action = "skipped_test_transaction";
    return res.status(200).json(log);
  }

  /* --- refunds / chargebacks: recorded, never counted as a sale --- */
  if (status === "refund" || status === "chargeback") {
    log.decisions.action = "skipped_" + status;
    log.decisions.note =
      "Refund reversal requires an adjustment upload (Google Ads API / Data Manager). Not sent.";
    return res.status(200).json(log);
  }

  /* --- only real payments convert --- */
  if (status !== "payment") {
    log.decisions.action = "skipped_status_" + status;
    return res.status(200).json(log);
  }

  /* --- duplicate guard (per instance) --- */
  const dedupeKey = transactionId || clickId + "|" + (revenue !== null ? revenue : "");
  pruneSeen();
  if (seen.has(dedupeKey)) {
    log.decisions.action = "skipped_duplicate";
    log.decisions.dedupe_key = dedupeKey;
    return res.status(200).json(log);
  }

  /* --- Google Ads config --- (env var wins, code fallback keeps prod working) --- */
  const conversionId =
    numericConversionId(process.env.GOOGLE_ADS_CONVERSION_ID) ||
    numericConversionId("AW-18570108057");
  const label =
    process.env.GOOGLE_ADS_CONVERSION_LABEL || "G6UgCNuAk74dEJm59ZZF";
  const currency =
    (currencyRaw && String(currencyRaw).trim().toUpperCase()) ||
    process.env.GOOGLE_ADS_CURRENCY ||
    "USD";

  if (!conversionId || !label) {
    log.decisions.action = "recorded_only_missing_google_config";
    log.decisions.required_env = ["GOOGLE_ADS_CONVERSION_ID", "GOOGLE_ADS_CONVERSION_LABEL"];
    // Still mark as seen so a later retry with config does not double count blindly.
    seen.set(dedupeKey, Date.now());
    return res.status(200).json(log);
  }

  const hasClickId = attr && (attr.g || attr.b || attr.w);
  if (!hasClickId) {
    log.decisions.action = "recorded_only_no_click_id";
    log.decisions.note =
      "cid carried no gclid/gbraid/wbraid — conversion cannot be attributed to an ad click.";
    seen.set(dedupeKey, Date.now());
    return res.status(200).json(log);
  }

  if (dryRun) {
    log.decisions.action = "dry_run_not_sent";
    seen.set(dedupeKey, Date.now());
    log.google_url = buildGoogleUrl({
      conversionId,
      label,
      value: revenue,
      currency,
      attr,
      orderId: transactionId
    });
    return res.status(200).json(log);
  }

  /* --- send conversion to Google Ads --- */
  const googleUrl = buildGoogleUrl({
    conversionId,
    label,
    value: revenue,
    currency,
    attr,
    orderId: transactionId
  });

  const result = await fireGoogleConversion(googleUrl);
  seen.set(dedupeKey, Date.now());

  log.decisions.action = result.ok ? "conversion_sent" : "google_call_failed";
  log.google = { status: result.status, ok: result.ok };
  if (result.error) log.google.error = result.error;
  log.conversion = {
    conversion_id: "AW-" + conversionId,
    label: label,
    value: revenue,
    currency: currency,
    order_id: transactionId || null,
    gross: gross
  };

  // Always 200 to Digistore24 so it does not retry-loop; details are in the body.
  return res.status(200).json(log);
};
